css:
.mo4-morph-cycle{
  --mo4mc-a:#6ee7ff; --mo4mc-b:#a78bfa; --mo4mc-ink:#eaf0ff; --mo4mc-dim:#7f8caa;
  position:relative; box-sizing:border-box; display:flex; align-items:center; gap:12px;
  width:100%; min-height:144px; padding:14px 16px; border-radius:16px; overflow:hidden;
  background:radial-gradient(115% 130% at 6% 0%, #1b2438 0%, #0c1018 62%);
  border:1px solid rgba(255,255,255,.07); color:var(--mo4mc-ink);
  font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.mo4-morph-cycle *{box-sizing:border-box}
.mo4-morph-cycle .mo4-morph-cycle-stage{position:relative;flex:0 0 auto;width:104px;height:104px}
.mo4-morph-cycle .mo4-morph-cycle-shell{position:absolute;inset:0;will-change:transform}
.mo4-morph-cycle .mo4-morph-cycle-svg{display:block;width:100%;height:100%;animation:mo4-morph-cycle-spin 14s linear infinite}
.mo4-morph-cycle .mo4-morph-cycle-shape{
  fill:rgba(110,231,255,.10); stroke:var(--mo4mc-a); stroke-width:2.6; stroke-linejoin:round;
  filter:drop-shadow(0 0 8px rgba(110,231,255,.45));
}
.mo4-morph-cycle .mo4-morph-cycle-halo{fill:none;stroke:var(--mo4mc-b);stroke-width:1.4;opacity:.34;filter:blur(2px)}
.mo4-morph-cycle .mo4-morph-cycle-orbit{
  position:absolute;left:50%;top:50%;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;
  background:#fff;box-shadow:0 0 10px 2px rgba(167,139,250,.85);
  animation:mo4-morph-cycle-orbit 2.6s linear infinite;
}
.mo4-morph-cycle .mo4-morph-cycle-meta{min-width:0;flex:1 1 auto}
.mo4-morph-cycle .mo4-morph-cycle-kicker{
  margin:0;font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:var(--mo4mc-dim);
}
.mo4-morph-cycle .mo4-morph-cycle-name{
  margin:2px 0 8px;font-size:19px;font-weight:650;letter-spacing:-.01em;
  background:linear-gradient(92deg,var(--mo4mc-a),var(--mo4mc-b));
  -webkit-background-clip:text;background-clip:text;color:transparent;
}
.mo4-morph-cycle .mo4-morph-cycle-name.mo4-morph-cycle-name--in{animation:mo4-morph-cycle-pop .5s cubic-bezier(.2,1.5,.4,1) both}
.mo4-morph-cycle .mo4-morph-cycle-bars{display:flex;align-items:flex-end;gap:3px;height:16px;margin-bottom:10px}
.mo4-morph-cycle .mo4-morph-cycle-bar{
  width:3px;height:16px;border-radius:2px;background:linear-gradient(180deg,var(--mo4mc-a),var(--mo4mc-b));
  transform-origin:bottom;transform:scaleY(.25);opacity:.75;
  animation:mo4-morph-cycle-wave 1.15s cubic-bezier(.45,0,.15,1) infinite alternate;
}
.mo4-morph-cycle .mo4-morph-cycle-bar:nth-child(2){animation-delay:.09s}
.mo4-morph-cycle .mo4-morph-cycle-bar:nth-child(3){animation-delay:.18s}
.mo4-morph-cycle .mo4-morph-cycle-bar:nth-child(4){animation-delay:.27s}
.mo4-morph-cycle .mo4-morph-cycle-bar:nth-child(5){animation-delay:.36s}
.mo4-morph-cycle .mo4-morph-cycle-btn{
  font:inherit;font-size:10px;letter-spacing:.06em;color:var(--mo4mc-ink);
  padding:5px 10px;border-radius:99px;cursor:pointer;
  border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.05);
  transition:transform .32s cubic-bezier(.2,1.6,.4,1),background .2s ease,border-color .2s ease;
}
.mo4-morph-cycle .mo4-morph-cycle-btn:hover{background:rgba(110,231,255,.14);border-color:rgba(110,231,255,.4);transform:translateY(-1px)}
.mo4-morph-cycle .mo4-morph-cycle-btn:active{transform:scale(.94)}
.mo4-morph-cycle .mo4-morph-cycle-btn:focus-visible{outline:2px solid var(--mo4mc-a);outline-offset:2px}
@keyframes mo4-morph-cycle-spin{to{transform:rotate(360deg)}}
@keyframes mo4-morph-cycle-orbit{from{transform:rotate(0deg) translateX(50px)}to{transform:rotate(360deg) translateX(50px)}}
@keyframes mo4-morph-cycle-wave{from{transform:scaleY(.22)}to{transform:scaleY(1)}}
@keyframes mo4-morph-cycle-pop{0%{transform:translateY(6px) scale(.9);opacity:0}100%{transform:none;opacity:1}}
@media (prefers-reduced-motion:reduce){
  .mo4-morph-cycle .mo4-morph-cycle-svg,
  .mo4-morph-cycle .mo4-morph-cycle-orbit,
  .mo4-morph-cycle .mo4-morph-cycle-bar,
  .mo4-morph-cycle .mo4-morph-cycle-name.mo4-morph-cycle-name--in{animation:none}
  .mo4-morph-cycle .mo4-morph-cycle-bar{transform:scaleY(.6)}
}

