var shape = root.querySelector('.mo4-morph-cycle-shape');
var halo  = root.querySelector('.mo4-morph-cycle-halo');
var shell = root.querySelector('.mo4-morph-cycle-shell');
var name  = root.querySelector('.mo4-morph-cycle-name');
var btn   = root.querySelector('.mo4-morph-cycle-btn');
if (!shape) return;

var N = 96, CX = 65, CY = 65;
var TAU = Math.PI * 2;

function radiusSquare(a){ var c = Math.abs(Math.cos(a)), s = Math.abs(Math.sin(a)); return 36 / Math.max(c, s); }
function radiusCircle(){ return 41; }
function radiusTri(a){
  var inr = 29, best = 1e9, k, ang, d;
  for (k = 0; k < 3; k++){
    ang = -Math.PI / 2 + TAU / 3 * k + Math.PI;
    d = Math.cos(a - ang);
    if (d > 0.0001) best = Math.min(best, inr / d);
  }
  return Math.min(best, 62);
}
function build(fn){ var out = [], i, a; for (i = 0; i < N; i++){ a = -Math.PI / 2 + TAU * i / N; out.push(fn(a)); } return out; }

var SHAPES = [
  { n:'square',   r:build(radiusSquare) },
  { n:'circle',   r:build(radiusCircle) },
  { n:'triangle', r:build(radiusTri) }
];

function toPath(rs){
  var d = '', i, a, x, y;
  for (i = 0; i < N; i++){
    a = -Math.PI / 2 + TAU * i / N;
    x = CX + Math.cos(a) * rs[i];
    y = CY + Math.sin(a) * rs[i];
    d += (i ? 'L' : 'M') + x.toFixed(2) + ' ' + y.toFixed(2);
  }
  return d + 'Z';
}
function render(rs){ var d = toPath(rs); shape.setAttribute('d', d); halo.setAttribute('d', d); }

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduce){ render(SHAPES[1].r); name.textContent = 'circle'; return; }

var idx = 0, from = SHAPES[0].r.slice(), cur = from.slice();
var to = SHAPES[1].r, t0 = performance.now(), dur = 820, hold = 700, settle = -1;

function ease(t){ return t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }

function advance(fast){
  from = cur.slice();
  idx = (idx + 1) % SHAPES.length;
  to = SHAPES[idx].r;
  t0 = performance.now();
  dur = fast ? 460 : 820;
  name.textContent = SHAPES[idx].n;
  name.classList.remove('mo4-morph-cycle-name--in');
  void name.offsetWidth;
  name.classList.add('mo4-morph-cycle-name--in');
}

function frame(now){
  var e = now - t0, p = Math.min(1, e / dur), k = ease(p), i;
  for (i = 0; i < N; i++) cur[i] = from[i] + (to[i] - from[i]) * k;
  render(cur);
  if (p >= 1){
    if (settle < 0) settle = now;
    var s = (now - settle) / 1000;
    var wob = 1 + Math.exp(-s * 6.5) * Math.sin(s * 26) * 0.09;
    shell.style.transform = 'scale(' + wob.toFixed(4) + ')';
    if (e > dur + hold){ settle = -1; shell.style.transform = 'scale(1)'; advance(false); }
  } else {
    settle = -1;
    shell.style.transform = 'scale(' + (1 + Math.sin(p * Math.PI) * 0.05).toFixed(4) + ')';
  }
  requestAnimationFrame(frame);
}
name.textContent = SHAPES[0].n;
requestAnimationFrame(frame);
btn.addEventListener('click', function(){ advance(true); });

