var track = root.querySelector('.mo4-infinity-trace-track');
var comet = root.querySelector('.mo4-infinity-trace-comet');
var head  = root.querySelector('.mo4-infinity-trace-head');
var grad  = root.querySelector('.mo4-infinity-trace-grad');
var pct   = root.querySelector('.mo4-infinity-trace-pct');
var sparks = root.querySelectorAll('.mo4-infinity-trace-spark');
if (!track || !comet) return;

var uid = 'mo4it' + Math.random().toString(36).slice(2, 9);
grad.setAttribute('id', uid);
comet.setAttribute('stroke', 'url(#' + uid + ')');

var len = track.getTotalLength();
var seg = len * 0.16;
comet.style.strokeDasharray = seg + ' ' + (len - seg);

function place(el, d){
  var p = track.getPointAtLength(((d % len) + len) % len);
  el.setAttribute('cx', p.x.toFixed(2));
  el.setAttribute('cy', p.y.toFixed(2));
  return p;
}

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduce){
  comet.style.strokeDashoffset = String(-len * 0.25);
  place(head, len * 0.41);
  for (var q = 0; q < sparks.length; q++) place(sparks[q], len * 0.41 - seg * 0.2 * (q + 1));
  pct.textContent = '68%';
  return;
}

var d = 0, speed = 118, target = 118, last = performance.now(), boost = 0;

root.addEventListener('pointerenter', function(){ target = 280; });
root.addEventListener('pointerleave', function(){ target = 118; });
root.addEventListener('pointerdown', function(){ boost = 1; target = 420; });
root.addEventListener('pointerup', function(){ target = 280; });

function frame(now){
  var dt = Math.min(50, now - last) / 1000; last = now;
  speed += (target - speed) * Math.min(1, dt * 5);
  boost *= Math.pow(0.02, dt);
  d = (d + speed * dt) % len;

  var sg = seg * (0.7 + speed / 340) * (1 + boost * 0.5);
  if (sg > len * 0.42) sg = len * 0.42;
  comet.style.strokeDasharray = sg.toFixed(1) + ' ' + (len - sg).toFixed(1);
  comet.style.strokeDashoffset = (-d).toFixed(1);

  place(head, d + sg);
  head.setAttribute('r', (4.4 + boost * 3).toFixed(2));
  for (var i = 0; i < sparks.length; i++){
    place(sparks[i], d + sg - sg * 0.22 * (i + 1));
    sparks[i].style.opacity = String(0.5 - i * 0.1);
  }
  pct.textContent = Math.round((d / len) * 100) + '%';
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

