js:
var cv = root.querySelector('.mo4-swarm-assemble-canvas');
var label = root.querySelector('.mo4-swarm-assemble-label');
var btn = root.querySelector('.mo4-swarm-assemble-btn');
if (!cv || !cv.getContext) return;
var ctx = cv.getContext('2d');
var w = 300, h = 144, N = 90;

function fit(){
  var r = cv.getBoundingClientRect();
  w = Math.max(60, r.width); h = Math.max(60, r.height);
  var dpr = Math.min(2, window.devicePixelRatio || 1);
  cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
fit();
if (typeof ResizeObserver === 'function'){ try { new ResizeObserver(fit).observe(cv); } catch (e) {} }
else window.addEventListener('resize', fit);

var FORMS = [
  { n:'ring', f:function(i,n){ var a = i / n * Math.PI * 2; var R = Math.min(w, h) * 0.30;
      return [w / 2 + Math.cos(a) * R * 1.05, h / 2 + Math.sin(a) * R]; } },
  { n:'wave', f:function(i,n){ var t = i / (n - 1);
      return [14 + (w - 28) * t, h / 2 + Math.sin(t * Math.PI * 3.2) * h * 0.22]; } },
  { n:'spiral', f:function(i,n){ var t = i / n, a = t * Math.PI * 5.5, R = Math.min(w, h) * (0.05 + t * 0.28);
      return [w / 2 + Math.cos(a) * R * 1.45, h / 2 + Math.sin(a) * R]; } },
  { n:'columns', f:function(i,n){ var cols = 6, per = Math.ceil(n / cols), c = Math.floor(i / per), k = i % per;
      var hs = [0.38,0.66,0.47,0.86,0.58,0.74];
      return [w * 0.20 + c * (w * 0.12), h * 0.80 - (k / (per - 1)) * h * 0.58 * hs[c]]; } }
];

var P = [], i;
for (i = 0; i < N; i++){
  var s = FORMS[0].f(i, N);
  P.push({ x:w / 2 + (Math.random() - .5) * w, y:h / 2 + (Math.random() - .5) * h,
           vx:0, vy:0, tx:s[0], ty:s[1], r:1 + Math.random() * 1.6, hue:i / N });
}

function setForm(k){
  var s, j;
  for (j = 0; j < N; j++){ s = FORMS[k].f(j, N); P[j].tx = s[0]; P[j].ty = s[1]; }
  label.textContent = 'assembling ' + FORMS[k].n;
}
function burst(power){
  for (var j = 0; j < N; j++){
    var a = Math.random() * Math.PI * 2, m = power * (0.5 + Math.random());
    P[j].vx += Math.cos(a) * m; P[j].vy += Math.sin(a) * m;
  }
}

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduce){
  ctx.fillStyle = '#0a0e16'; ctx.fillRect(0, 0, w, h);
  for (i = 0; i < N; i++){
    ctx.fillStyle = 'rgba(94,234,212,.85)';
    ctx.beginPath(); ctx.arc(P[i].tx, P[i].ty, P[i].r + .6, 0, 6.284); ctx.fill();
  }
  return;
}

var form = 0, nextAt = performance.now() + 2400;
var mx = -999, my = -999;
root.addEventListener('pointermove', function(e){
  var r = cv.getBoundingClientRect(); mx = e.clientX - r.left; my = e.clientY - r.top;
});
root.addEventListener('pointerleave', function(){ mx = -999; my = -999; });
btn.addEventListener('click', function(){ burst(7); nextAt = performance.now() + 900; });

function frame(now){
  if (now > nextAt){ burst(3.4); form = (form + 1) % FORMS.length; setForm(form); nextAt = now + 2600; }
  ctx.fillStyle = 'rgba(9,12,20,.38)';
  ctx.fillRect(0, 0, w, h);
  for (var j = 0; j < N; j++){
    var p = P[j];
    p.vx += (p.tx - p.x) * 0.035; p.vy += (p.ty - p.y) * 0.035;
    var dx = p.x - mx, dy = p.y - my, d2 = dx * dx + dy * dy;
    if (d2 < 2600 && d2 > 0.01){
      var d = Math.sqrt(d2), f = (1 - d / 51) * 2.6;
      p.vx += dx / d * f; p.vy += dy / d * f;
    }
    p.vx *= 0.885; p.vy *= 0.885;
    p.x += p.vx; p.y += p.vy;
    var sp = Math.min(1, Math.sqrt(p.vx * p.vx + p.vy * p.vy) / 6);
    var g = Math.round(180 + 60 * p.hue), b = Math.round(255 - 60 * p.hue);
    ctx.fillStyle = 'rgba(' + Math.round(90 + 120 * sp) + ',' + g + ',' + b + ',' + (0.55 + 0.45 * (1 - sp)) + ')';
    ctx.beginPath(); ctx.arc(p.x, p.y, p.r + sp * 1.2, 0, 6.284); ctx.fill();
  }
  requestAnimationFrame(frame);
}
setForm(0);
requestAnimationFrame(frame);

