var svg = root.querySelector('.mo4-liquid-blob-svg');
var goo = root.querySelector('.mo4-liquid-blob-goo');
var filt = root.querySelector('.mo4-liquid-blob-filter');
var grad = root.querySelector('.mo4-liquid-blob-grad');
var core = root.querySelector('.mo4-liquid-blob-core');
var drops = root.querySelectorAll('.mo4-liquid-blob-drop');
var pct = root.querySelector('.mo4-liquid-blob-pct');
if (!goo) return;

var salt = Math.random().toString(36).slice(2, 9);
var fid = 'mo4lbf' + salt, gid = 'mo4lbg' + salt;
filt.setAttribute('id', fid);
grad.setAttribute('id', gid);
goo.style.filter = 'url(#' + fid + ')';
goo.setAttribute('fill', 'url(#' + gid + ')');

var CX = 54, CY = 59;
var seeds = [], i;
for (i = 0; i < drops.length; i++){
  seeds.push({ sp:0.5 + i * 0.19, ph:i * 1.27, base:19 + (i % 3) * 5, amp:7 + (i % 4) * 2.4, wob:0.9 + i * 0.31, r0:parseFloat(drops[i].getAttribute('r')) });
}

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduce){
  for (i = 0; i < drops.length; i++){
    var a0 = i / drops.length * 6.283;
    drops[i].setAttribute('transform', 'translate(' + (Math.cos(a0) * 21).toFixed(1) + ' ' + (Math.sin(a0) * 16).toFixed(1) + ')');
  }
  pct.textContent = '72%';
  return;
}

var t0 = performance.now(), px = 0, py = 0, ox = 0, oy = 0, splash = 0, sv = 0;

root.addEventListener('pointermove', function(e){
  var r = svg.getBoundingClientRect();
  px = ((e.clientX - r.left) / r.width * 170 - CX) * 0.42;
  py = ((e.clientY - r.top) / r.height * 118 - CY) * 0.42;
});
root.addEventListener('pointerleave', function(){ px = 0; py = 0; });
root.addEventListener('pointerdown', function(){ sv += 3.4; });

function frame(now){
  var t = (now - t0) / 1000;
  ox += (px - ox) * 0.09; oy += (py - oy) * 0.09;
  sv += (0 - splash) * 0.10; sv *= 0.90; splash += sv;

  for (var j = 0; j < drops.length; j++){
    var s = seeds[j];
    var a = t * s.sp + s.ph;
    var rad = s.base + Math.sin(t * s.wob + s.ph) * s.amp + splash * 9;
    var x = CX + Math.cos(a) * rad * 1.35 + ox;
    var y = CY + Math.sin(a) * rad + oy;
    drops[j].setAttribute('cx', x.toFixed(2));
    drops[j].setAttribute('cy', y.toFixed(2));
    drops[j].setAttribute('r', (s.r0 * (1 + Math.sin(t * 1.7 + s.ph) * 0.18 + splash * 0.12)).toFixed(2));
  }
  core.setAttribute('cx', (CX + ox * 0.5).toFixed(2));
  core.setAttribute('cy', (CY + oy * 0.5).toFixed(2));
  core.setAttribute('r', (21 + Math.sin(t * 1.25) * 2.2 - splash * 2).toFixed(2));
  pct.textContent = Math.floor((t * 13) % 100) + '%';
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

