var pctEl = root.querySelector('.mo4-sweep-bar-pct');
var note = root.querySelector('.mo4-sweep-bar-note');
var btn = root.querySelector('.mo4-sweep-bar-btn');
if (!pctEl) return;

var STEPS = [0.16, 0.39, 0.58, 0.79, 1];
var NOTES = ['hashing chunks', 'uploading 3 of 8', 'uploading 7 of 8', 'verifying checksum', 'upload complete'];
var LEAD = 1900, GAP = 640, TAIL = 1500;

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduce){
  root.classList.add('mo4-sweep-bar--det', 'mo4-sweep-bar--done');
  root.style.setProperty('--mo4sb-p', '1');
  pctEl.textContent = '100%';
  note.textContent = NOTES[4];
  root.setAttribute('aria-valuenow', '100');
  return;
}

var t0 = performance.now(), shown = 0, target = 0, lastNote = -1, det = false;

function setNote(k){
  if (k === lastNote) return;
  lastNote = k;
  note.textContent = NOTES[k];
  note.style.animation = 'none';
  void note.offsetWidth;
  note.style.animation = '';
}
function reset(){
  t0 = performance.now(); shown = 0; target = 0; lastNote = -1; det = false;
  root.classList.remove('mo4-sweep-bar--det', 'mo4-sweep-bar--done');
  root.style.setProperty('--mo4sb-p', '0');
  root.removeAttribute('aria-valuenow');
  note.textContent = 'negotiating connection';
  pctEl.textContent = '--';
}
btn.addEventListener('click', reset);

function frame(now){
  var e = now - t0;
  if (e < LEAD){
    target = 0;
    if (det){ det = false; root.classList.remove('mo4-sweep-bar--det', 'mo4-sweep-bar--done'); }
  } else {
    var k = Math.min(STEPS.length - 1, Math.floor((e - LEAD) / GAP));
    target = STEPS[k];
    setNote(k);
    if (!det){ det = true; root.classList.add('mo4-sweep-bar--det'); }
    root.style.setProperty('--mo4sb-p', String(target));
    if (k === STEPS.length - 1) root.classList.add('mo4-sweep-bar--done');
    if (e > LEAD + (STEPS.length - 1) * GAP + TAIL) reset();
  }
  shown += (target - shown) * 0.10;
  if (e >= LEAD){
    var v = Math.round(shown * 100);
    pctEl.textContent = v + '%';
    root.setAttribute('aria-valuenow', String(v));
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

