var btn = root.querySelector('.mo4-skeleton-shine-btn');
var real = root.querySelector('.mo4-skeleton-shine-real');
var READY = 'mo4-skeleton-shine--ready';
var timers = [];

function clear(){ for (var i = 0; i < timers.length; i++) clearTimeout(timers[i]); timers = []; }
function show(){ root.classList.add(READY); if (real) real.setAttribute('aria-busy', 'false'); }
function hide(){ root.classList.remove(READY); if (real) real.setAttribute('aria-busy', 'true'); }

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduce){ show(); return; }

function cycle(){
  clear();
  hide();
  timers.push(setTimeout(show, 2300));
  timers.push(setTimeout(cycle, 5200));
}
btn.addEventListener('click', cycle);
cycle();

