var dial = root.querySelector('.mo4-ring-elastic-dial');
var arc  = root.querySelector('.mo4-ring-elastic-arc');
var knob = root.querySelector('.mo4-ring-elastic-knob');
var val  = root.querySelector('.mo4-ring-elastic-val');
var range = root.querySelector('.mo4-ring-elastic-range');
if (!arc) return;

var C = 2 * Math.PI * 42;
arc.style.strokeDasharray = C.toFixed(2) + ' ' + C.toFixed(2);

function paint(p){
