  knob.setAttribute('transform', 'rotate(' + (360 * p).toFixed(2) + ' 50 50)');
  var v = Math.max(0, Math.round(p * 100));
  val.textContent = String(v);
  dial.setAttribute('aria-valuenow', String(Math.min(100, v)));
  if (c > 0.985) root.classList.add('mo4-ring-elastic--full');
  else root.classList.remove('mo4-ring-elastic--full');
}

