var nextAt = performance.now() + 1150, manualUntil = 0;

range.addEventListener('input', function(){
  target = parseFloat(range.value) / 100;
  manualUntil = performance.now() + 5000;
});

function frame(now){
  if (now > manualUntil && now > nextAt){
    step = (step + 1) % TARGETS.length;
    target = TARGETS[step];
    nextAt = now + (target === 0 ? 1500 : 1150);
  }
  vel += (target - value) * 0.115;
  vel *= 0.815;
  value += vel;
  paint(value);
  if (now > manualUntil) range.value = String(Math.max(0, Math.min(100, Math.round(value * 100))));
