.mo4-stage-check{
  --mo4st-a:#818cf8; --mo4st-ok:#34d399; --mo4st-ink:#e9eefb; --mo4st-dim:#6f7c9a;
  box-sizing:border-box; width:100%; min-height:144px; padding:13px 15px; border-radius:16px;
  background:linear-gradient(160deg,#141a29,#090d15);
  border:1px solid rgba(255,255,255,.07); color:var(--mo4st-ink); overflow:hidden;
  font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.mo4-stage-check *{box-sizing:border-box}
.mo4-stage-check .mo4-stage-check-head{display:flex;align-items:center;gap:7px;margin-bottom:9px}
.mo4-stage-check .mo4-stage-check-title{font-size:12px;font-weight:650;letter-spacing:-.01em}
.mo4-stage-check .mo4-stage-check-pill{
  font-size:8px;letter-spacing:.14em;text-transform:uppercase;padding:2px 7px;border-radius:99px;
  color:#04120c;background:linear-gradient(90deg,#34d399,#a3e635);
  transform:scale(0);opacity:0;transform-origin:left center;
  transition:transform .5s cubic-bezier(.2,1.7,.36,1),opacity .3s ease;
}
.mo4-stage-check.mo4-stage-check--done .mo4-stage-check-pill{transform:scale(1);opacity:1}
.mo4-stage-check .mo4-stage-check-count{
  margin-left:auto;font-size:9.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--mo4st-dim);
  font-variant-numeric:tabular-nums;
}
.mo4-stage-check .mo4-stage-check-btn{
  font:inherit;font-size:9.5px;letter-spacing:.06em;color:var(--mo4st-dim);
  padding:3px 8px;border-radius:99px;cursor:pointer;
  border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.04);
  transition:transform .3s cubic-bezier(.2,1.6,.4,1),color .2s ease,background .2s ease;
}
.mo4-stage-check .mo4-stage-check-btn:hover{color:var(--mo4st-ink);background:rgba(129,140,248,.18)}
.mo4-stage-check .mo4-stage-check-btn:active{transform:scale(.9)}
.mo4-stage-check .mo4-stage-check-btn:focus-visible{outline:2px solid var(--mo4st-a);outline-offset:2px}
.mo4-stage-check .mo4-stage-check-body{position:relative}
.mo4-stage-check .mo4-stage-check-rail{
  position:absolute;left:7px;top:11px;bottom:11px;width:2px;border-radius:2px;
  background:rgba(255,255,255,.08);overflow:hidden;
}
.mo4-stage-check .mo4-stage-check-railfill{
