  background:linear-gradient(180deg,var(--mo4st-a),var(--mo4st-ok));
  transition:transform .7s cubic-bezier(.22,1.3,.36,1);
}
.mo4-stage-check .mo4-stage-check-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:5px}
.mo4-stage-check .mo4-stage-check-item{
  display:flex;align-items:center;gap:9px;height:21px;
  opacity:.42;transform:translateX(-6px);
  transition:opacity .4s ease,transform .6s cubic-bezier(.2,1.5,.36,1);
}
.mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--run,
.mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--done{opacity:1;transform:none}
.mo4-stage-check .mo4-stage-check-node{
  position:relative;flex:0 0 auto;width:16px;height:16px;border-radius:50%;
