  transition:box-shadow .35s ease,background .35s ease;
}
.mo4-stage-check .mo4-stage-check-spin{
  position:absolute;inset:1px;border-radius:50%;
  border:2px solid transparent;border-top-color:var(--mo4st-a);border-right-color:var(--mo4st-a);
  opacity:0;transform:scale(.5);
  transition:opacity .25s ease,transform .4s cubic-bezier(.2,1.6,.4,1);
}
.mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--run .mo4-stage-check-spin{
  opacity:1;transform:scale(1);animation:mo4-stage-check-spin .68s linear infinite;
}
.mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--done .mo4-stage-check-node{
  background:rgba(52,211,153,.16);box-shadow:0 0 0 2px rgba(52,211,153,.55) inset;
  animation:mo4-stage-check-flash .55s cubic-bezier(.2,1.6,.4,1);
}
.mo4-stage-check .mo4-stage-check-tick{position:absolute;inset:0;width:100%;height:100%;display:block}
.mo4-stage-check .mo4-stage-check-tickpath{
  fill:none;stroke:var(--mo4st-ok);stroke-width:3.2;stroke-linecap:round;stroke-linejoin:round;
  stroke-dasharray:18;stroke-dashoffset:18;
  transition:stroke-dashoffset .42s cubic-bezier(.65,0,.35,1);
}
.mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--done .mo4-stage-check-tickpath{stroke-dashoffset:0}
.mo4-stage-check .mo4-stage-check-label{
  font-size:10.5px;letter-spacing:-.005em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  transition:color .35s ease;color:#c6d1e8;
}
.mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--done .mo4-stage-check-label{color:var(--mo4st-ink)}
.mo4-stage-check .mo4-stage-check-time{
  margin-left:auto;font-size:9px;color:var(--mo4st-dim);font-variant-numeric:tabular-nums;
  opacity:0;transform:translateX(4px);transition:opacity .35s ease,transform .5s cubic-bezier(.2,1.5,.4,1);
}
.mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--done .mo4-stage-check-time{opacity:1;transform:none}
@keyframes mo4-stage-check-spin{to{transform:rotate(360deg)}}
@keyframes mo4-stage-check-flash{0%{transform:scale(1)}40%{transform:scale(1.28)}100%{transform:scale(1)}}
@media (prefers-reduced-motion:reduce){
  .mo4-stage-check .mo4-stage-check-item,
  .mo4-stage-check .mo4-stage-check-tickpath,
  .mo4-stage-check .mo4-stage-check-railfill,
  .mo4-stage-check .mo4-stage-check-time,
  .mo4-stage-check .mo4-stage-check-pill{transition:none}
  .mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--done .mo4-stage-check-node{animation:none}
  .mo4-stage-check .mo4-stage-check-item.mo4-stage-check-item--run .mo4-stage-check-spin{animation:none}
}

