var items = root.querySelectorAll('.mo4-stage-check-item');
var fill = root.querySelector('.mo4-stage-check-railfill');
var count = root.querySelector('.mo4-stage-check-count');
var btn = root.querySelector('.mo4-stage-check-btn');
var RUN = 'mo4-stage-check-item--run', DONE = 'mo4-stage-check-item--done';
var n = items.length, timers = [];

function clear(){ for (var i = 0; i < timers.length; i++) clearTimeout(timers[i]); timers = []; }
function at(ms, fn){ timers.push(setTimeout(fn, ms)); }
function done(k){
  items[k].classList.remove(RUN);
  items[k].classList.add(DONE);
  fill.style.transform = 'scaleY(' + ((k + 1) / n).toFixed(3) + ')';
  count.textContent = (k + 1) + ' of ' + n;
}

var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (reduce){
  for (var r = 0; r < n; r++) items[r].classList.add(DONE);
  fill.style.transform = 'scaleY(1)';
  count.textContent = n + ' of ' + n;
  root.classList.add('mo4-stage-check--done');
  return;
}

function reset(){
  clear();
  root.classList.remove('mo4-stage-check--done');
  for (var i = 0; i < n; i++) items[i].classList.remove(RUN, DONE);
  fill.style.transform = 'scaleY(0)';
  count.textContent = '0 of ' + n;
}

function run(){
  reset();
  var t = 260;
  for (var i = 0; i < n; i++){
    (function(k, start){
      at(start, function(){ items[k].classList.add(RUN); });
      at(start + 760, function(){ done(k); });
    })(i, t);
    t += 820;
  }
  at(t + 120, function(){ root.classList.add('mo4-stage-check--done'); });
  at(t + 1700, run);
}
btn.addEventListener('click', run);
run();
